    assert tax_for(1000, Decimal("0.0825")) == 82
    assert isinstance(tax_for(1000, 0.0825), int)


def test_tax_for_rounds_half_even():
    assert tax_for(50, 0.05) == 2  # 2.5 -> 2
    assert tax_for(70, 0.05) == 4  # 3.5 -> 4


def test_tax_for_float_rate_is_exact():
    # 0.0825 as a binary float is slightly below 0.0825; 200 * rate must still be 16.5 -> 16
    assert tax_for(200, 0.0825) == 16
    assert tax_for(600, 0.0825) == 50  # 49.5 -> 50"
